    const words = Array.from({ length: n }, () => r.str(r.int(1, maxLen), pool));
    const cmp = (a, b) => {
      for (let i = 0; i < Math.min(a.length, b.length); i++) if (a[i] !== b[i]) return rank.get(a[i]) - rank.get(b[i]);
      return a.length - b.length;
    };
    // big lists are always valid; small ones are sorted only some of the time, so loops and prefix clashes show up
    if (big || r.bool(0.6)) words.sort(cmp);
