function alphabetOrder(words: string[]): string {
  const after = new Map<string, Set<string>>(), indeg = new Map<string, number>();
  for (const w of words) for (const ch of w) if (!after.has(ch)) { after.set(ch, new Set()); indeg.set(ch, 0); }
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i], b = words[i + 1], m = Math.min(a.length, b.length);
    let j = 0;
    while (j < m && a[j] === b[j]) j++;
    if (j === m) {
      if (a.length > b.length) return ""; // a word before its own prefix
      continue;
    }
    if (!after.get(a[j])!.has(b[j])) {
      after.get(a[j])!.add(b[j]);
      indeg.set(b[j], indeg.get(b[j])! + 1);
    }
  }
  const queue: string[] = [];
  for (const [ch, d] of indeg) if (d === 0) queue.push(ch);
  let order = "";
  for (let i = 0; i < queue.length; i++) {
    const ch = queue[i];
    order += ch;
    for (const next of after.get(ch)!) {
      indeg.set(next, indeg.get(next)! - 1);
      if (indeg.get(next) === 0) queue.push(next);
    }
  }
  return order.length === after.size ? order : "";
}

