class Solution:
    def alphabetOrder(self, words: List[str]) -> str:
        after = {ch: set() for w in words for ch in w}
        indeg = {ch: 0 for ch in after}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    if y not in after[x]:
                        after[x].add(y)
                        indeg[y] += 1
                    break
            else:
                if len(a) > len(b):
                    return ""  # a word before its own prefix
        queue = deque(ch for ch in indeg if indeg[ch] == 0)
        order = []
        while queue:
            ch = queue.popleft()
            order.append(ch)
            for nxt in after[ch]:
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    queue.append(nxt)
        return "".join(order) if len(order) == len(after) else ""

