function alphabetOrder(words: string[]): string {
  const after = new Map<string, Set<string>>();
  for (const w of words) for (const ch of w) if (!after.has(ch)) after.set(ch, new Set());
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i], b = words[i + 1], m = Math.min(a.length, b.length);
    let j = 0;
    while (j < m && a[j] === b[j]) j++;
    if (j === m) { if (a.length > b.length) return ""; continue; }
    after.get(a[j])!.add(b[j]);
  }
  const state = new Map<string, number>(); // missing = unvisited, 1 = on the current path, 2 = done
  const post: string[] = [];
  const visit = (ch: string): boolean => {
    if (state.get(ch) === 1) return false; // back to a letter on the path: a loop
    if (state.get(ch) === 2) return true;
    state.set(ch, 1);
    for (const next of after.get(ch)!) if (!visit(next)) return false;
    state.set(ch, 2);
    post.push(ch);
    return true;
  };
  for (const ch of after.keys()) if (!visit(ch)) return "";
  return post.reverse().join("");
}

