        after = {ch: set() for w in words for ch in w}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    after[x].add(y)
                    break
            else:
                if len(a) > len(b):
                    return ""
        state = {}  # 1 = on the current path, 2 = done
        post = []

        def visit(ch):
            if state.get(ch) == 1:
                return False
            if state.get(ch) == 2:
                return True
            state[ch] = 1
            for nxt in after[ch]:
                if not visit(nxt):
                    return False
            state[ch] = 2
            post.append(ch)
            return True

        for ch in after:
            if not visit(ch):
                return ""
        return "".join(reversed(post))

